public class Student {
    // 1. Declare private instance variables
    private String id;
    private String fullName;
    private String major;
    private int totalCredits;
    private double totalQualityPoints;
    private String academicStanding;

    // 2. Parameterized constructor with validation
    public Student(String id, String fullName, String major) {
        if (id == null || id.trim().isEmpty()) {
            throw new IllegalArgumentException("Student ID cannot be null or empty.");
        }
        if (fullName == null || fullName.trim().isEmpty()) {
            throw new IllegalArgumentException("Student name cannot be null or empty.");
        }
        this.id = id.trim();
        this.fullName = fullName.trim();
        this.major = (major != null) ? major.trim() : "Undeclared";
        this.totalCredits = 0;
        this.totalQualityPoints = 0.0;
        this.academicStanding = "GOOD STANDING";
    }

    // 3. Add course grade with validation
    public boolean addCourseGrade(double gradePoint, int creditHours) {
        if (gradePoint < 0.0 || gradePoint > 4.0 || creditHours <= 0) {
            System.err.println("Invalid grade or credit hours provided.");
            return false;
        }
        this.totalQualityPoints += (gradePoint * creditHours);
        this.totalCredits += creditHours;
        updateStanding();
        return true;
    }

    // 4. Calculate GPA safely
    public double calculateGPA() {
        if (this.totalCredits == 0) return 0.0;
        return this.totalQualityPoints / this.totalCredits;
    }

    // 5. Update academic standing
    public void updateStanding() {
        double gpa = calculateGPA();
        if (this.totalCredits == 0) {
            this.academicStanding = "GOOD STANDING";
        } else if (gpa >= 3.75) {
            this.academicStanding = "HONORS";
        } else if (gpa >= 2.00) {
            this.academicStanding = "GOOD STANDING";
        } else {
            this.academicStanding = "ACADEMIC PROBATION";
        }
    }

    // 6. Formatted transcript output
    public void printTranscript() {
        System.out.println("=======================================================");
        System.out.println("           OFFICIAL ACADEMIC TRANSCRIPT               ");
        System.out.println("=======================================================");
        System.out.printf("Student ID:        %s%n", id);
        System.out.printf("Full Name:         %s%n", fullName);
        System.out.printf("Academic Major:    %s%n", major);
        System.out.printf("Total Credits:     %d%n", totalCredits);
        System.out.printf("Cumulative GPA:    %.2f%n", calculateGPA());
        System.out.printf("Academic Standing: %s%n", academicStanding);
        System.out.println("=======================================================\n");
    }

    // Getters
    public String getId() { return id; }
    public String getFullName() { return fullName; }
    public String getMajor() { return major; }
    public int getTotalCredits() { return totalCredits; }
    public String getAcademicStanding() { return academicStanding; }
}

